-- ==============================================================================
-- 3. TABLA MAESTRA DE INGREDIENTES (957 alimentos auditados de BEDCA)
-- ==============================================================================
CREATE TABLE ingredients (
    id INT PRIMARY KEY,
    name VARCHAR(200) NOT NULL UNIQUE,
    nutriscore_aprox CHAR(1) NOT NULL CHECK (nutriscore_aprox IN ('A', 'B', 'C', 'D', 'E')),
    energy_kcal NUMERIC(7, 2),
    protein_g NUMERIC(7, 4),
    fat_g NUMERIC(7, 4),
    carbs_g NUMERIC(7, 4),
    fiber_g NUMERIC(7, 4),
    saturated_fat_g NUMERIC(7, 4),
    sugar_g NUMERIC(7, 4),
    sodium_mg NUMERIC(9, 4),
    vitamin_c_mg NUMERIC(8, 4),
    calcium_mg NUMERIC(8, 4),
    iron_mg NUMERIC(7, 4),
    potassium_mg NUMERIC(8, 4),
    subcategory_id INT NOT NULL REFERENCES food_subcategories(id) ON DELETE RESTRICT
);

COMMENT ON TABLE ingredients IS 'Catálogo BEDCA (957 alimentos). Todos los valores nutricionales corresponden a 100 g de porción comestible.';

